import React, { useEffect, useState } from "react";
import { socket } from "../api/socket";
import PollResults from "./PollResults.js";
import TimerBar from "./TimerBar";

export default function TeacherView() {
  const [question, setQuestion] = useState("");
  const [options, setOptions] = useState(["", ""]);
  const [duration, setDuration] = useState(60);
  const [poll, setPoll] = useState(null);

  useEffect(() => {
    socket.on("poll:update", ({ poll }) => {
      setPoll(poll);
    });
    socket.on("poll:closed", () => {
      setPoll(prev => prev ? { ...prev, isActive: false } : null);
    });
    return () => {
      socket.off("poll:update");
      socket.off("poll:closed");
    };
  }, []);

  const canAskNew =
    !poll || (poll && !poll.isActive); // all answered or timer finished

  const handleCreate = e => {
    e.preventDefault();
    if (!canAskNew) return;
    const cleanOptions = options.map(o => o.trim()).filter(Boolean);
    if (!question.trim() || cleanOptions.length < 2) return;

    socket.emit("teacher:createPoll", {
      question: question.trim(),
      options: cleanOptions,
      duration: Number(duration) || 60
    });

    setQuestion("");
    setOptions(["", ""]);
  };

  const handleOptionChange = (value, idx) => {
    const copy = [...options];
    copy[idx] = value;
    setOptions(copy);
  };

  const addOption = () => setOptions([...options, ""]);

  const clearPoll = () => {
    socket.emit("teacher:clearPoll");
    setPoll(null);
  };

  return (
    <div className="teacher-view">
      <section className="poll-form">
        <h3>Create Poll</h3>
        <form onSubmit={handleCreate}>
          <label>
            Question
            <input
              value={question}
              onChange={e => setQuestion(e.target.value)}
              placeholder="Type your question"
            />
          </label>

          <div className="options-list">
            {options.map((opt, idx) => (
              <input
                key={idx}
                value={opt}
                onChange={e => handleOptionChange(e.target.value, idx)}
                placeholder={`Option ${idx + 1}`}
              />
            ))}
          </div>

          <button type="button" onClick={addOption}>
            + Add option
          </button>

          <label>
            Time limit (seconds)
            <input
              type="number"
              min="5"
              max="300"
              value={duration}
              onChange={e => setDuration(e.target.value)}
            />
          </label>

          <button type="submit" disabled={!canAskNew}>
            {canAskNew ? "Start Poll" : "Wait for answers..."}
          </button>

          {poll && !poll.isActive && (
            <button type="button" onClick={clearPoll}>
              Clear Poll
            </button>
          )}
        </form>
      </section>

      <section className="poll-live">
        <h3>Live Poll</h3>
        {poll ? (
          <>
            <p className="poll-question">{poll.question}</p>
            {poll.isActive && <TimerBar expiresAt={poll.expiresAt} />}
            <PollResults poll={poll} />
          </>
        ) : (
          <p>No active poll.</p>
        )}
      </section>
    </div>
  );
}
